private val pending = new ConcurrentHashMap[String, Promise[Reply]]()

def call(body: String)(implicit scheduler: Scheduler): Future[Reply] = {
  val id = UUID.randomUUID().toString
  val p  = Promise[Reply]()
  pending.put(id, p)                                     // register BEFORE send
  transport.send(Request(id, body))
  val timeoutF = after(5.seconds, scheduler)(Future.failed(NoReply(id)))
  Future.firstCompletedOf(Seq(p.future, timeoutF))
        .andThen { case _ => pending.remove(id) }         // late reply then dropped
}

def onReply(reply: Reply): Unit =
  Option(pending.remove(reply.correlationId)).foreach(_.trySuccess(reply))

